tintor", "obligatorio": true, "hoyPorDefecto": false}, {"id": "c_n9j2qp89", "tipo": "tabla_verificacion", "ancho": "completo", "etiqueta": "Elementos de emergencia", "ayuda": "B = Bueno · M = Malo · N/A = No aplica", "filas": ["TRIÁNGULOS / CONOS", "LLAVE DE AJUSTE", "GATO", "MANGA DE VIENTO", "LINTERNA", "BOTIQUÍN", "DIM''S (IDENTIFICADOR DE CONDUCTOR)", "CÁMARA DE FATIGA", "CAJA DE HERRAMIENTAS O MALLA DE RESTRICCIÓN", "CHALECOS REFLECTIVOS"], "columnas": ["SI", "NO"], "obligatorio": true}, {"id": "c_uzfk8ut0", "tipo": "tabla_verificacion", "ancho": "completo", "etiqueta": "5. Sistema eléctrico", "ayuda": "B = Bueno · M = Malo · N/A = No aplica", "filas": ["LUCES DE ALTA Y BAJAS", "LUCES DE FRENO", "LUCES DE CRUCE O GIRO", "LUCES DE RETROCESO", "LUCES INTERMITENTES", "LUZ DE CABINA", "BOCINA O CORNETA", "ALARMA DE RETROCESO", "AIRE ACONDICIONADO", "LIMPIAPARABRISAS", "INDICADORES DE COMBUSTIBLE Y OTROS"], "columnas": ["B", "M", "N/A"], "obligatorio": true}, {"id": "c_cvs4f8cg", "tipo": "tabla_verificacion", "ancho": "completo", "etiqueta": "6. Sistema mecánico", "ayuda": "B = Bueno · M = Malo · N/A = No aplica", "filas": ["VELOCÍMETRO / ODÓMETRO", "RADIADOR", "DEPÓSITO DE AGUA DEL MOTOR", "CAÑO DE ESCAPE / SILENCIADOR", "SISTEMA DE DIRECCIÓN"], "columnas": ["B", "M", "N/A"], "obligatorio": true}, {"id": "c_vyie6ivw", "tipo": "tabla_verificacion", "ancho": "completo", "etiqueta": "7. Neumáticos", "ayuda": "B = Bueno · M = Malo · N/A = No aplica", "filas": ["DELANTERO DERECHO", "DELANTERO IZQUIERDO", "TRASERO DERECHO", "TRASERO IZQUIERDO", "REPUESTO 1", "CUÑAS DE SEGURIDAD"], "columnas": ["B", "M", "N/A"], "obligatorio": true}, {"id": "c_pvs7hzio", "tipo": "tabla_verificacion", "ancho": "completo", "etiqueta": "8. Tapicería", "ayuda": "B = Bueno · M = Malo · N/A = No aplica", "filas": ["ASIENTO DEL CONDUCTOR", "ASIENTO DEL COPILOTO / ACOMPAÑANTE", "ASIENTO TRASERO", "TODOS LOS ASIENTOS CON APOYA CABEZA"], "columnas": ["B", "M", "N/A"], "obligatorio": true}, {"id": "c_ykl1cq99", "tipo": "tabla_verificacion", "ancho": "completo", "etiqueta": "9. Cristalería", "ayuda": "B = Bueno · M = Malo · N/A = No aplica", "filas": ["PARABRISAS", "VIDRIOS PUERTAS DELANTERAS", "VIDRIOS PUERTAS TRASERAS", "VIDRIO TRASERO", "ESPEJOS RETROVISORES LATERALES"], "columnas": ["B", "M", "N/A"], "obligatorio": true}, {"id": "c_chj755nf", "tipo": "tabla_verificacion", "ancho": "completo", "etiqueta": "10. Especificaciones especiales", "ayuda": "Varios ítems aplican solo a vehículos con remolque: marque N/A cuando no correspondan.", "filas": ["CINTURÓN DE SEGURIDAD DE 3 PUNTOS PARA TODOS LOS OCUPANTES", "ASIENTOS CON REPOSACABEZAS", "RECORDATORIO DE USO DEL CINTURÓN DE SEGURIDAD", "ANCLAJES DE CINTURONES DE SEGURIDAD SEGÚN REQUISITOS DE LA INDUSTRIA", "SISTEMA DE FRENOS ANTIBLOQUEO QUE CUMPLA CON LOS REQUISITOS DE LA INDUSTRIA", "PROTECCIÓN ACTIVA ANTIVUELCO (ARP) EN EL REMOLQUE", "PROTECCIÓN CONTRA VUELCOS SEGÚN LOS REQUISITOS DE LA INDUSTRIA", "LOS NEUMÁTICOS DEBEN SER DEL MISMO TAMAÑO / MISMO FABRICANTE POR EJE", "NEUMÁTICOS ADECUADOS A LA CARGA/VELOCIDAD, INFLADOS CORRECTAMENTE, PROFUNDIDAD MÍNIMA DE LA BANDA DE RODADURA 1,6 MM (75 %)", "INDICADORES DE POSICIÓN EN LAS TUERCAS DE LOS NEUMÁTICOS", "NEUMÁTICOS DELANTEROS CON BANDA DE RODADURA MÍNIMA DE 3,0 MM Y EL MISMO TAMAÑO/MARCA", "GUARDABARROS EN TODOS LOS NEUMÁTICOS", "NO SE PERMITEN NEUMÁTICOS RECONSTRUIDOS (PRINCIPALMENTE EN EL EJE DELANTERO)", "CABINA QUE CUMPLE CON LOS REQUISITOS DE LA INDUSTRIA", "PROTECCIÓN ANTIEMPOTRAMIENTO DELANTERA Y TRASERA PARA EL REMOLQUE", "PROTECCIÓN LATERAL CONTRA COLISIÓN", "VIDRIO DE SEGURIDAD PARA PARABRISAS", "DOS CALZAS PARA RUEDAS", "SISTEMA DE CONTROL ELECTRÓNICO DE ESTABILIDAD", "TODOS LOS ACCESORIOS Y ESCOTILLAS ASEGURADOS SIN FUGAS EN CASO DE VUELCO", "2 EXTINTORES MÍNIMO (UNO DE 2 KG EN CABINA Y OTRO DE 6 KG MÍNIMO EN REMOLQUE)", "CINTURONES DE SEGURIDAD Y SISTEMAS DE RETENCIÓN SEGÚN REQUISITOS DE LA INDUSTRIA", "MÍNIMO 2 PUERTAS (UNA NORMAL Y UNA DE EMERGENCIA)", "PUERTA(S) DE EMERGENCIA CLARAMENTE MARCADAS", "MARCAS REFLECTANTES EN LA PARTE TRASERA Y EN LOS LATERALES", "DIMS SEGÚN CONTRATO", "ALARMA SONORA DE MARCHA ATRÁS"], "columnas": ["SI", "NO", "N/A"], "obligatorio": true}, {"id": "c_4zw9xa3k", "tipo": "seccion", "ancho": "completo", "ayuda": "", "etiqueta": "Hallazgos y observaciones", "obligatorio": false}, {"id": "c_x7eedtjv", "tipo": "parrafo", "ancho": "completo", "ayuda": "", "etiqueta": "Hallazgos y observaciones", "obligatorio": false}, {"id": "c_zhwjr64d", "tipo": "foto", "ancho": "completo", "ayuda": "Adjunte fotos del equipo o hallazgos encontrados", "etiqueta": "Evidencia fotográfica", "maxFotos": 5, "obligatorio": false}, {"id": "c_pja1wj0t", "tipo": "seccion", "ancho": "completo", "ayuda": "", "etiqueta": "Validación de la inspección", "obligatorio": false}, {"id": "c_pac56t4u", "tipo": "texto", "ancho": "tercio", "ayuda": "", "etiqueta": "Nombre y apellido", "obligatorio": true}, {"id": "c_fel6246h", "tipo": "texto", "ancho": "tercio", "ayuda": "", "etiqueta": "Cédula", "obligatorio": true}, {"id": "c_id25owf7", "tipo": "texto", "ancho": "tercio", "ayuda": "", "etiqueta": "Cargo", "obligatorio": false}, {"id": "c_5935a0l7", "tipo": "firma", "ancho": "completo", "ayuda": "", "etiqueta": "Firma", "obligatorio": true}, {"id": "c_253j2d54", "tipo": "seccion", "ancho": "completo", "ayuda": "", "etiqueta": "Inspector adicional 2", "obligatorio": false, "grupoAdicional": 2}, {"id": "c_i3qk2iag", "tipo": "texto", "ancho": "tercio", "ayuda": "", "etiqueta": "Nombre y apellido", "obligatorio": false, "grupoAdicional": 2}, {"id": "c_l58kxo9t", "tipo": "texto", "ancho": "tercio", "ayuda": "", "etiqueta": "Cédula", "obligatorio": false, "grupoAdicional": 2}, {"id": "c_7e8g8jdp", "tipo": "texto", "ancho": "tercio", "ayuda": "", "etiqueta": "Cargo", "obligatorio": false, "grupoAdicional": 2}, {"id": "c_0lvsnujz", "tipo": "firma", "ancho": "completo", "ayuda": "", "etiqueta": "Firma", "obligatorio": false, "gr