INSERT INTO public.formularios ("id", "titulo", "descripcion", "campos", "activo", "creado_por", "creado_en", "actualizado_en", "codigo", "emision", "revision", "rol", "plantilla_id") VALUES ('8dc98422-4689-4a0b-a49d-69ea3919ba3d', 'Inspección de equipos de protección personal (EPP)', 'Verificación periódica del estado, certificación y uso adecuado de cascos, lentes, calzado, arneses y respiradores.', '[{"id": "c_09lzrk79", "tipo": "seccion", "ancho": "completo", "ayuda": "", "etiqueta": "1. Datos generales", "obligatorio": false}, {"id": "c_ufu6py06", "tipo": "fecha", "ancho": "tercio", "ayuda": "", "etiqueta": "Fecha", "obligatorio": true, "hoyPorDefecto": true}, {"id": "c_ftlo4qdb", "tipo": "texto", "ancho": "mitad", "ayuda": "", "etiqueta": "Centro de trabajo / Proyecto", "obligatorio": true}, {"id": "c_xvh7katq", "tipo": "tabla_verificacion", "ancho": "completo", "etiqueta": "2. Inspección de equipos de protección personal (EPP)", "ayuda": "Marque SI si cumple, NO si presenta falla o N/A si no aplica", "filas": ["1.1 Casco: Se observan averías, fisuras o deformaciones en el casco", "1.2 Casco: Se utiliza el casco apropiado para la actividad que realizan", "1.3 Casco: Posee sistema de suspensión y tafilete instalado correctamente", "2.1 Lentes: Presentan ralladuras o manchas en el visor que dificulten la visión", "2.2 Lentes: Se utilizan lentes o gafas de seguridad adecuados al riesgo", "3.1 Calzado: Se encuentran los zapatos de seguridad con puntera en buenas condiciones", "3.2 Calzado: La suela y el diseño son los adecuados para la actividad", "4.1 Careta de soldar: Se encuentra en buen estado mecánico y sin fisuras", "4.2 Careta de soldar: El vidrio / visor oscuro utilizado es el grado apropiado", "5.1 Soldadura: Se encuentran los guantes y mangas de soldador en buen estado", "6.1 Guantes de carnaza / tela: Están sin roturas, deshilachados o deteriorados", "7.1 Guantes de neopreno / químicos: Son los apropiados contra las sustancias manipuladas", "7.2 Señalización: Existen avisos preventivos alusivos al uso de guantes específicos", "8.1 Mascarillas contra polvo: Las mascarillas utilizadas son las apropiadas (N95 / FFP2)", "9.1 Respiradores: Los respiradores de media cara son los apropiados al contaminante", "9.2 Respiradores: Los cartuchos / filtros y bandas elásticas están en óptimas condiciones", "10.1 Arnés de seguridad: Todas las cintas y bandas del arnés están en buenas condiciones", "10.2 Arnés de seguridad: Posee cabo de vida (eslinga) con amortiguador de impacto", "10.3 Arnés de seguridad: Los ganchos y mosquetones poseen pasador con doble seguro", "10.4 Arnés de seguridad: Costuras intactas sin decoloración ni daño químico", "11.1 Protección auditiva: Se evidencia la utilización de tapones auditivos donde aplica", "11.2 Protección auditiva: Los tapones tienen la tasa de reducción de ruido necesaria", "12.1 Orejeras: En áreas de más de 85 dB se utiliza protección auditiva tipo copa / orejera", "12.2 Orejeras: Las almohadillas y diadema se encuentran en buen estado"], "columnas": ["SI", "NO", "N/A"], "obligatorio": true}, {"id": "c_ydshlv76", "tipo": "seccion", "ancho": "completo", "ayuda": "", "etiqueta": "Hallazgos y observaciones", "obligatorio": false}, {"id": "c_mf4nnkm9", "tipo": "parrafo", "ancho": "completo", "ayuda": "", "etiqueta": "Hallazgos y observaciones", "obligatorio": false}, {"id": "c_5d0p92k3", "tipo": "foto", "ancho": "completo", "ayuda": "Adjunte fotos del equipo o hallazgos encontrados", "etiqueta": "Evidencia fotográfica", "maxFotos": 5, "obligatorio": false}, {"id": "c_8p6fvdhr", "tipo": "seccion", "ancho": "completo", "ayuda": "", "etiqueta": "Validación de la inspección", "obligatorio": false}, {"id": "c_59c81do6", "tipo": "texto", "ancho": "tercio", "ayuda": "", "etiqueta": "Nombre y apellido", "obligatorio": true}, {"id": "c_ouz1egnt", "tipo": "texto", "ancho": "tercio", "ayuda": "", "etiqueta": "Cédula", "obligatorio": true}, {"id": "c_b34kuqaa", "tipo": "texto", "ancho": "tercio", "a